/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO ADMINISTRADOR  (exclusivo rol ADMIN; el Router ya lo verifica,
   pero aqui se vuelve a comprobar como segunda barrera de seguridad)
   Pantallas: ADMIN | ADMIN_ACTIVAR | ADMIN_DESACTIVAR | ADMIN_ROL
   ===================================================================== */
const ctx = $('▶️ Entrada Admin').first().json;
const usuarios = filasReales($('📄 USUARIOS - Leer').all(), 'telegram_user');
const logs = filasReales($input.all(), 'timestamp');

const texto = String(ctx.texto || '').trim();
const pantalla = String(ctx.pantalla_actual || 'ADMIN').toUpperCase();
const paso = String(ctx.paso_actual || '0');
const rol = String(ctx.rol || 'USER').toUpperCase();
const yo = String(ctx.telegram_user);
const d = leerDatos(ctx.datos_parciales);

/* --- segunda barrera de permisos --- */
if (rol !== 'ADMIN')
  return salida('🔒 Esta sección es exclusiva del rol ADMIN.\n' +
                'Tu rol actual es ' + rol + '.\n\nEscribe /menu para volver.',
                'MENU', '0', {}, 'SIN_PERMISO_ADMIN');

const MENU =
  '🛡️ ADMINISTRADOR\n' +
  'Gestión de usuarios y auditoría del sistema.\n\n' +
  '1  Consultar usuarios\n' +
  '2  Consultar logs recientes\n' +
  '3  Activar usuario\n' +
  '4  Desactivar usuario\n' +
  '5  Cambiar rol de un usuario\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 1 Consultar usuarios\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'ADMIN', '0', {}, 'MENU_ADMIN');

function listadoUsuarios(us) {
  return us.map(function (u, i) {
    const ok = esVerdadero(u.permitido);
    return (i + 1) + ')  ' + (ok ? '🟢' : '🔴') + ' ' + (u.nombre || '(sin nombre)') +
           '\n      🆔 ' + u.telegram_user + '  ·  🔑 ' + (u.rol || 'USER') +
           '  ·  ' + (ok ? 'HABILITADO' : 'BLOQUEADO');
  }).join('\n');
}
function fila(u, cambios) {
  return {
    telegram_user: String(u.telegram_user),
    nombre: (cambios && cambios.nombre) || u.nombre,
    rol: (cambios && cambios.rol) || u.rol,
    permitido: (cambios && cambios.permitido) || u.permitido
  };
}
function pedirUsuario(us, verbo, destino) {
  if (us.length === 0)
    return salida('📭 No hay usuarios que cumplan esa condición.\n\n' + MENU,
                  'ADMIN', '0', {}, 'SIN_USUARIOS');
  return salida('🔧 ¿A qué usuario quieres ' + verbo + '?\n\n' + listadoUsuarios(us) + '\n\n' +
                'Escribe el número (1 a ' + us.length + ').\n\n9 Volver   ·   /cancelar Cancelar',
                destino, '1', { opciones: us.map(function (u) { return String(u.telegram_user); }) },
                'SELECCION_PEDIDA');
}

/* ------------------------------------------------------------------ MENU */
if (pantalla === 'ADMIN') {
  if (texto === '1') {
    const act = usuarios.filter(function (u) { return esVerdadero(u.permitido); }).length;
    const adm = usuarios.filter(function (u) { return String(u.rol || '').toUpperCase() === 'ADMIN'; }).length;
    return salida('👥 USUARIOS REGISTRADOS (' + usuarios.length + ')\n' +
                  '🟢 Habilitados: ' + act + '   🔴 Bloqueados: ' + (usuarios.length - act) +
                  '   🔑 Admins: ' + adm + '\n\n' +
                  (usuarios.length ? listadoUsuarios(usuarios.slice(0, 25)) : '   (sin registros)') +
                  '\n\n' + MENU, 'ADMIN', '0', {}, 'CONSULTA_USUARIOS');
  }
  if (texto === '2') {
    const ult = logs.slice(-20).reverse();
    if (ult.length === 0)
      return salida('📭 Todavía no hay movimientos registrados en LOGS.\n\n' + MENU,
                    'ADMIN', '0', {}, 'LOGS_VACIOS');
    const txt = ult.map(function (l) {
      return '• ' + l.timestamp + '\n   👤 ' + l.telegram_user + '  📺 ' + l.pantalla +
             '\n   ⌨️ "' + String(l.opcion_elegida || '').slice(0, 30) + '"  →  ' + l.resultado;
    }).join('\n');
    return salida('📜 ÚLTIMOS ' + ult.length + ' MOVIMIENTOS\n(total histórico: ' + logs.length + ')\n\n' +
                  txt + '\n\n' + MENU, 'ADMIN', '0', {}, 'CONSULTA_LOGS');
  }
  if (texto === '3')
    return pedirUsuario(usuarios.filter(function (u) { return !esVerdadero(u.permitido); }),
                        'activar', 'ADMIN_ACTIVAR');
  if (texto === '4')
    return pedirUsuario(usuarios.filter(function (u) {
      return esVerdadero(u.permitido) && String(u.telegram_user) !== yo;
    }), 'desactivar', 'ADMIN_DESACTIVAR');
  if (texto === '5')
    return pedirUsuario(usuarios, 'cambiarle el rol', 'ADMIN_ROL');
  if (texto === '9')
    return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                  'MENU', '0', {}, 'VOLVER');
  return salida(opcionInvalida('En Administrador espero un número del 1 al 5, o 9.') + '\n\n' + MENU,
                'ADMIN', '0', {}, 'OPCION_INVALIDA');
}

/* ---------------------------------------------------- ACCIONES SOBRE USER */
if (pantalla === 'ADMIN_ACTIVAR' || pantalla === 'ADMIN_DESACTIVAR' || pantalla === 'ADMIN_ROL') {
  if (texto === '9') return salida(MENU, 'ADMIN', '0', {}, 'VOLVER');
  const ids = Array.isArray(d.opciones) ? d.opciones : [];

  if (paso === '1') {
    const n = parseInt(texto, 10);
    if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
      return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                    pantalla, '1', d, 'SELECCION_INVALIDA');
    const u = usuarios.find(function (r) { return String(r.telegram_user) === String(ids[n - 1]); });
    if (!u) return salida('⚠️ No encontré ese usuario.\n\n' + MENU, 'ADMIN', '0', {}, 'NO_ENCONTRADO');

    if (pantalla === 'ADMIN_ROL') {
      d.telegram_user = String(u.telegram_user);
      return salida('🔑 Usuario: ' + (u.nombre || u.telegram_user) + '\nRol actual: ' + u.rol + '\n\n' +
                    '¿Qué rol le asigno?\n\n1  USER   (acceso normal)\n2  ADMIN  (acceso total)\n\n' +
                    '💡 Recomendado: 1 USER\n9 Volver   ·   /cancelar Cancelar',
                    'ADMIN_ROL', '2', d, 'ROL_PEDIDO');
    }
    if (pantalla === 'ADMIN_DESACTIVAR' && String(u.telegram_user) === yo)
      return salida('⚠️ No puedes desactivarte a ti mismo.\n' +
                    'Si lo hicieras, perderías el acceso al bot.\n\n' + MENU,
                    'ADMIN', '0', {}, 'AUTOBLOQUEO_EVITADO');

    const activar = (pantalla === 'ADMIN_ACTIVAR');
    return salida((activar ? '🟢 Usuario habilitado.' : '🔴 Usuario bloqueado.') + '\n\n' +
                  '👤 ' + (u.nombre || '(sin nombre)') + '\n🆔 ' + u.telegram_user +
                  '\n🔑 ' + u.rol + '\n✅ Permitido: ' + (activar ? 'TRUE' : 'FALSE') + '\n\n' + MENU,
                  'ADMIN', '0', {},
                  (activar ? 'USUARIO_ACTIVADO:' : 'USUARIO_DESACTIVADO:') + u.telegram_user,
                  'ACTUALIZAR', fila(u, { permitido: activar ? 'TRUE' : 'FALSE' }));
  }

  if (pantalla === 'ADMIN_ROL' && paso === '2') {
    const r = { '1': 'USER', '2': 'ADMIN' }[texto];
    if (!r) return salida(opcionInvalida('Espero 1 (USER) o 2 (ADMIN).'),
                          'ADMIN_ROL', '2', d, 'OPCION_INVALIDA');
    const u = usuarios.find(function (x) { return String(x.telegram_user) === String(d.telegram_user); });
    if (!u) return salida('⚠️ No encontré ese usuario.\n\n' + MENU, 'ADMIN', '0', {}, 'NO_ENCONTRADO');
    if (String(u.telegram_user) === yo && r === 'USER') {
      const otros = usuarios.filter(function (x) {
        return String(x.rol || '').toUpperCase() === 'ADMIN' && String(x.telegram_user) !== yo;
      });
      if (otros.length === 0)
        return salida('⚠️ Eres el único administrador del sistema.\n' +
                      'Si te quitas el rol ADMIN nadie podría administrar el bot.\n' +
                      'Primero nombra a otro administrador.\n\n' + MENU,
                      'ADMIN', '0', {}, 'ULTIMO_ADMIN_PROTEGIDO');
    }
    return salida('🔑 Rol actualizado.\n\n👤 ' + (u.nombre || u.telegram_user) +
                  '\nAntes: ' + u.rol + '\nAhora: ' + r + '\n\n' + MENU,
                  'ADMIN', '0', {}, 'ROL_CAMBIADO:' + u.telegram_user + '->' + r,
                  'ACTUALIZAR', fila(u, { rol: r }));
  }
  return salida(MENU, 'ADMIN', '0', {}, 'PASO_DESCONOCIDO');
}

return salida(MENU, 'ADMIN', '0', {}, 'PANTALLA_DESCONOCIDA');

const r = $('🧠 Lógica de Admin').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
